	colHeaderContainer.layoutMode = 'HORIZONTAL';
	colHeaderContainer.primaryAxisAlignItems = 'CENTER';  // Center horizontally
	colHeaderContainer.counterAxisAlignItems = 'MAX';  // Align to bottom

